import {newProject,garmentNames} from './templates.js';import {exportSvg,esc} from './render.js';import {uiIcon} from './ui-icons.js';import {union} from './core.js';import {visible} from './model.js';
const templateCache=new Map(),recentCache=new Map();
function croppedPreview(p){const os=p.views.front,b=union(os.filter(o=>visible(p,'front',o)),os);const svg=exportSvg(p,'front');if(!b)return svg;const pad=Math.max(12,Math.max(b.w,b.h)*.08);return svg.replace('viewBox="0 0 700 700"',`viewBox="${b.x-pad} ${b.y-pad} ${Math.max(1,b.w)+pad*2} ${Math.max(1,b.h)+pad*2}"`);}
export function templatePreview(kind){if(!templateCache.has(kind)){const p=newProject(kind);templateCache.set(kind,croppedPreview(p));}return templateCache.get(kind);}
export function templateCards(selected='tee'){return Object.entries(garmentNames).map(([kind,name])=>`<button class="template ${kind===selected?'active':''}" data-new="${kind}" aria-pressed="${kind===selected}">${templatePreview(kind)}<strong>${name}</strong><span>${kind==='blank'?'Hoja vacía':'Frente + espalda'}<small>${kind==='blank'?'700 × 700':'Vector editable'}</small></span></button>`).join('');}
export function projectThumbnail(p){const signature=JSON.stringify([p.updated,p.activeVariant,p.views.front]);let cached=recentCache.get(p.id);if(cached?.signature===signature)return cached.svg;const svg=croppedPreview(p);recentCache.set(p.id,{signature,svg});if(recentCache.size>100)recentCache.delete(recentCache.keys().next().value);return svg;}
export function recentCards(ps){return ps.map(p=>`<article class="recent" data-recent-id="${p.id}"><button class="recent-open" data-open="${p.id}"><span class="recent-preview">${projectThumbnail(p)}</span><span class="recent-name">${esc(p.name)}</span><small>${garmentNames[p.kind]||'Diseño'} · ${new Date(p.updated).toLocaleDateString('es-AR')}</small></button><button class="recent-more icon-button" data-project-menu="${p.id}" aria-label="Opciones de ${esc(p.name)}" title="Opciones del proyecto">${uiIcon('more')}</button></article>`).join('');}
export function brandMark(){return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 4H10C3 4 3 10 10 12l4 1c7 2 7 7 0 7H6" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/><path d="m17 2 3 2-3 2M7 18l-3 2 3 2" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linejoin="round"/></svg>';}
